insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_140'
from (values
('127.888.d.21.A',3,'A student checks a bladder tank for cracks and chafing and a metal tank for corrosion and leaks. She is:','["inspecting a metal, bladder or integral fuel tank", "buying a tank", "ignoring the tank", "painting the tank"]'::jsonb,0,'Tank inspection.','original'),
('127.888.d.21.A',4,'A sign that an integral wing tank is leaking is:','["a dry cabin", "fuel staining on the wing skin", "a quiet engine", "a bright finish"]'::jsonb,1,'Stain means leak.','original'),
('127.888.d.21.B',3,'A mechanic moves a fuel selector through every position and checks for positive detents and no leaks. She is:','["removing the tank", "ignoring the valve", "inspecting a fuel selector valve", "painting the valve"]'::jsonb,2,'Selector check.','original'),
('127.888.d.21.B',4,'A selector valve that feels loose or doesn''t stop at each tank should be:','["ignored", "oiled only", "painted", "repaired or replaced"]'::jsonb,3,'Fix loose selector.','original'),
('127.888.d.21.C',3,'A technician drains a small sample from the lowest point of the tank into a clear cup and looks for water. She is:','["draining a fuel system sump", "painting a tank", "filling a tank", "washing a tank"]'::jsonb,0,'Sump drain.','original'),
('127.888.d.21.C',4,'Water in a fuel sample usually settles at the:','["side of the cup", "bottom of the cup, because it is heavier than fuel", "top of the cup", "center of the cup"]'::jsonb,1,'Water sinks.','original'),
('127.888.d.21.D',3,'A mechanic removes a fuel strainer bowl, cleans the screen and replaces the gasket. She is:','["adding oil", "ignoring the screen", "servicing a fuel system strainer", "painting the strainer"]'::jsonb,2,'Strainer service.','original'),
('127.888.d.21.D',4,'Debris found in a fuel strainer screen may indicate:','["perfect flow", "clean fuel", "a new engine", "contamination in the tank or lines"]'::jsonb,3,'Debris clue.','original'),
('127.888.d.21.E',3,'A mechanic looks in the manual for the fuel system inspection steps and the servicing and troubleshooting charts. She is:','["identifying and locating fuel system operating instructions, inspection procedures and troubleshooting information", "ignoring the manual", "using memory", "guessing"]'::jsonb,0,'Fuel system data.','original'),
('127.888.d.21.E',4,'Fuel system instructions for a specific aircraft are found in:','["a magazine", "its maintenance manual", "a pamphlet", "a flyer"]'::jsonb,1,'AMM source.','original'),
('127.888.d.22.A',3,'A student labels the armature, field coils, commutator and brushes of a DC generator. She is:','["labeling tires", "labeling seats", "identifying the components of generators, DC generation systems and DC power distribution", "labeling lights"]'::jsonb,2,'DC gen parts.','original'),
('127.888.d.22.A',4,'The commutator of a DC generator:','["stores fuel", "cools the shaft", "drives the prop", "converts the internal AC into DC output"]'::jsonb,3,'Commutator.','original'),
('127.888.d.22.B',3,'A student explains how a spinning armature cuts the field and produces current that flows to the bus. She is:','["explaining the basic operation of generators, DC generation systems and DC power distribution", "avoiding generators", "describing tires", "describing seats"]'::jsonb,0,'DC gen operation.','original'),
('127.888.d.22.B',4,'A DC generator''s output voltage depends on the speed of the armature and the:','["paint color", "strength of the magnetic field", "seat position", "tire pressure"]'::jsonb,1,'Field strength.','original'),
('127.888.d.22.C',3,'A student labels the stator, rotor and rectifier of an alternator. She is:','["labeling seats", "labeling tires", "identifying the components of alternators, AC generation systems and AC power distribution", "labeling lights"]'::jsonb,2,'Alternator parts.','original'),
('127.888.d.22.C',4,'Many light aircraft alternators use a diode rectifier to:','["add voltage", "store fuel", "cool the engine", "change AC output into DC for the bus"]'::jsonb,3,'Rectifier.','original'),
('127.888.d.22.D',3,'A student explains how a spinning rotor induces current in the stator windings and sends power to the aircraft. She is:','["explaining the basic operation of alternators, AC generation systems and AC power distribution", "avoiding alternators", "describing tires", "describing seats"]'::jsonb,0,'Alternator operation.','original'),
('127.888.d.22.D',4,'Compared with a DC generator, an alternator usually:','["produces less", "produces more output at low engine rpm", "has more brushes", "weighs more"]'::jsonb,1,'Alternator advantage.','original'),
('127.888.d.22.E',3,'A mechanic describes how a voltage regulator keeps the bus near 14 volts while the alternator speed changes. She is:','["describing tires", "avoiding regulators", "identifying the components and explaining the basic operation of voltage regulators, overvoltage and reverse current protection", "describing seats"]'::jsonb,2,'Regulator.','original'),
('127.888.d.22.E',4,'An overvoltage relay protects the electrical system by:','["cooling wires", "raising voltage", "adding load", "disconnecting the alternator if voltage is too high"]'::jsonb,3,'Overvoltage.','original'),
('127.888.d.22.F',3,'A student labels the DC input, oscillator and AC output of an inverter on a diagram. She is:','["identifying the components and explaining the basic operation of inverter systems", "describing tires", "avoiding inverters", "describing seats"]'::jsonb,0,'Inverter.','original'),
('127.888.d.22.F',4,'An inverter in an aircraft converts:','["AC into DC", "DC power into AC power", "light into sound", "heat into fuel"]'::jsonb,1,'Inverter job.','original'),
('127.888.d.22.G',3,'A mechanic checks a wire chart for the right gauge for a 20-amp load over a 15-foot run. She is:','["guessing the gauge", "ignoring the load", "explaining aircraft wiring size and type selection criteria", "using any wire"]'::jsonb,2,'Wire sizing.','original'),
('127.888.d.22.G',4,'Choosing wire that is too small for the current can cause:','["extra cooling", "a better signal", "less resistance", "overheating and voltage drop"]'::jsonb,3,'Undersized wire.','original'),
('127.888.d.22.H',3,'A technician explains that a braided shield around a cable keeps radio noise from reaching sensitive circuits. She is:','["explaining the purpose of aircraft wiring shielding", "avoiding shields", "ignoring noise", "painting cables"]'::jsonb,0,'Shielding.','original'),
('127.888.d.22.H',4,'Shielding on a wire protects against:','["fuel leaks", "electromagnetic interference", "tire wear", "rust only"]'::jsonb,1,'EMI.','original'),
('127.888.d.22.I',3,'A mechanic checks the bonding jumpers and the lightning diverter strips on a radome. She is:','["painting the radome", "ignoring the strips", "explaining the purpose of aircraft bonding and lightning protection", "avoiding bonding"]'::jsonb,2,'Bonding and lightning.','original'),
('127.888.d.22.I',4,'Bonding jumpers help by:','["adding noise", "insulating parts", "adding heat", "providing a low-resistance path between parts"]'::jsonb,3,'Jumpers.','original'),
('127.888.d.22.J',3,'A mechanic checks the breaker, the fuse, the switch and the ground before replacing a failed pump. She is:','["describing basic electrical system troubleshooting practices", "guessing", "replacing everything", "ignoring the circuit"]'::jsonb,0,'Troubleshooting.','original'),
('127.888.d.22.J',4,'A good first step in electrical troubleshooting is to:','["remove the battery", "verify the symptom and check simple items such as breakers and fuses", "paint the panel", "replace the wiring harness"]'::jsonb,1,'Start simple.','original'),
('127.888.d.22.K',3,'Before soldering a terminal, a student strips the wire, cleans it and chooses rosin-core solder. She is:','["using no flux", "skipping prep", "identifying soldering preparation techniques, types of solder and flux usage", "using acid flux"]'::jsonb,2,'Solder prep.','original'),
('127.888.d.22.K',4,'For electrical work, the correct type of flux is:','["water", "acid flux", "oil", "rosin flux, not acid flux"]'::jsonb,3,'Rosin flux.','original'),
('127.888.d.22.L',3,'A student sorts ring terminals, butt splices and rocker switches by what they do. She is:','["identifying types of aircraft electrical connectors, splices, terminals and switches", "sorting seats", "sorting tires", "sorting lights"]'::jsonb,0,'Connectors.','original'),
('127.888.d.22.L',4,'A ring terminal is often chosen over a spade terminal where:','["no power exists", "vibration could cause the connection to loosen", "no wire exists", "no vibration exists"]'::jsonb,1,'Ring terminals.','original'),
('127.888.d.22.M',3,'A mechanic checks electrolyte level, cleans corrosion and tests voltage on a battery. She is:','["avoiding batteries", "dumping batteries", "describing methods of aircraft battery troubleshooting and maintenance", "painting batteries"]'::jsonb,2,'Battery care.','original'),
('127.888.d.22.M',4,'A lead-acid battery''s corrosion can be neutralized with:','["paint", "fuel", "grease", "baking soda and water"]'::jsonb,3,'Neutralize acid.','original'),
('127.888.d.22.N',3,'A student learns that probing an energized circuit can cause shocks, arcs and damage. She is researching:','["the risks of testing electrical systems, including energized circuits", "tire brands", "paint choices", "no risks"]'::jsonb,0,'Energized tests.','original'),
('127.888.d.22.N',4,'Before working on a circuit, a technician should first:','["use wet hands", "turn the power off and disconnect the battery if possible", "wear metal jewelry", "touch live wires"]'::jsonb,1,'Power off.','original'),
('127.888.d.22.O',3,'A student learns that connecting a ground power unit to the wrong terminal can damage avionics. She is researching:','["no risks", "paint choices", "the risks of connecting and disconnecting external power", "tire brands"]'::jsonb,2,'External power.','original'),
('127.888.d.22.O',4,'Connecting external power with the wrong polarity can:','["improve the radios", "charge the fuel", "cool the cabin", "damage electrical equipment"]'::jsonb,3,'Polarity.','original'),
('127.888.d.22.P',3,'A mechanic is warned about chafed wires near fuel lines and sharp edges. She is researching:','["the risks of maintenance in areas containing aircraft wiring", "tire brands", "paint choices", "no risks"]'::jsonb,0,'Wiring areas.','original'),
('127.888.d.22.P',4,'Damaged insulation on wire near a fuel line can lead to:','["cooler fuel", "arcing and fire", "better flow", "less noise"]'::jsonb,1,'Arcing.','original'),
('127.888.d.22.Q',3,'A student learns that unsecured wire bundles can rub on structure over time. She is researching:','["tire brands", "paint choices", "the risks of improperly routing and securing wires and wire bundles", "no risks"]'::jsonb,2,'Routing.','original'),
('127.888.d.22.Q',4,'Wire bundles are secured with clamps and ties to prevent:','["extra weight", "extra flexibility", "better looks", "chafing and vibration damage"]'::jsonb,3,'Secure bundles.','original'),
('127.888.d.22.R',3,'A mechanic uses a terminal that''s too small for the wire gauge. She is creating:','["risks of improper selection or installation of wire terminals", "a cooler joint", "no risks", "a stronger joint"]'::jsonb,0,'Terminal sizing.','original'),
('127.888.d.22.R',4,'A loose or undersized terminal can cause:','["a cooler wire", "heat and a failed connection", "extra power", "better signals"]'::jsonb,1,'Bad terminal.','original'),
('127.888.d.22.S',3,'A student learns that cold solder joints and overheated joints cause failures. She is researching:','["tire brands", "no risks", "the risks of improper soldering practices", "paint choices"]'::jsonb,2,'Soldering risks.','original'),
('127.888.d.22.S',4,'A dull, grainy solder joint is a sign of:','["a clean joint", "a perfect joint", "a strong joint", "a poor (cold) joint"]'::jsonb,3,'Cold joint.','original'),
('127.888.d.23.A',3,'A student follows a wire run through the fuselage, checking clamps, slack and clearance from sharp edges. She is:','["inspecting aircraft wiring installation and routing", "painting wires", "ignoring wiring", "cutting wires"]'::jsonb,0,'Wire inspection.','original'),
('127.888.d.23.A',4,'Wire bundles should have slack between clamps so that:','["they stay tight", "they don''t pull on connectors during vibration", "they hang loose", "they touch hot parts"]'::jsonb,1,'Slack.','original'),
('127.888.d.23.B',3,'A mechanic strips a wire, crimps a terminal onto it and tugs it to test the crimp. She is:','["painting wire", "ignoring wire", "performing wire terminating and splicing", "buying wire"]'::jsonb,2,'Crimping.','original'),
('127.888.d.23.B',4,'A crimped terminal should be pulled gently to:','["heat it", "loosen it", "cool it", "verify the crimp is secure"]'::jsonb,3,'Pull test.','original'),
('127.888.d.23.C',3,'A student looks at a circuit diagram and labels the switch, the circuit breaker and the lamp. She is:','["identifying components using a wiring circuit diagram", "identifying lights only", "identifying seats", "identifying tires"]'::jsonb,0,'Read the diagram.','original'),
('127.888.d.23.C',4,'On a wiring diagram, a wavy line with a dot at each end usually stands for:','["a bulb", "a resistor", "a ground", "a switch"]'::jsonb,1,'Schematic symbol.','original'),
('127.888.d.23.D',3,'A mechanic heats the joint, flows solder onto it and holds it still until it cools. She is:','["cutting wires", "taping wires", "connecting aircraft wires using a solder joint", "gluing wires"]'::jsonb,2,'Soldering.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_140'
from (values
('127.888.d.23.D',4,'A good solder joint should be:','["cracked", "dull and grainy", "burned", "shiny and smooth"]'::jsonb,3,'Good joint.','original'),
('127.888.d.23.E',3,'A student''s lamp circuit won''t work, so she checks the bulb, the switch and the ground path with a meter. She is:','["troubleshooting a simple airframe electrical circuit", "replacing the plane", "ignoring the lamp", "painting the lamp"]'::jsonb,0,'Troubleshoot circuit.','original'),
('127.888.d.23.E',4,'If a bulb tests good and power reaches the socket, the fault may be a:','["new bulb", "bad ground connection", "strong battery", "good wire"]'::jsonb,1,'Ground fault.','original'),
('127.888.d.23.F',3,'A mechanic installs a braided strap between a control surface and the wing to carry current. She is:','["painting the wing", "isolating the surface", "installing bonding jumpers to electrically connect two isolated components", "ignoring the strap"]'::jsonb,2,'Bonding jumper.','original'),
('127.888.d.23.F',4,'Before installing a bonding jumper, the contact surfaces should be:','["left corroded", "oiled", "painted", "cleaned to bare metal"]'::jsonb,3,'Clean contact.','original'),
('127.888.d.23.G',3,'A student uses an ohmmeter on a heater element to check its value. She is:','["measuring the resistance of an electrical system component", "measuring tires", "measuring seats", "measuring fuel"]'::jsonb,0,'Resistance.','original'),
('127.888.d.23.G',4,'An ohmmeter reading of infinity across a heater element means:','["full power", "the element is open", "the element is good", "a short circuit"]'::jsonb,1,'Open element.','original'),
('127.888.d.23.H',3,'A technician switches on the beacon, the position lights and the landing light and watches each one. She is:','["removing lights", "ignoring lights", "inspecting and testing anti-collision, position and landing lights for proper operation", "painting lights"]'::jsonb,2,'Light test.','original'),
('127.888.d.23.H',4,'Navigation (position) lights on an airplane show red on the left wing and green on the:','["nose", "tail", "belly", "right wing"]'::jsonb,3,'Nav light colors.','original'),
('127.888.d.23.I',3,'A student looks at a schematic and points out the transformer, the diodes and the filter capacitor of a rectifier. She is:','["identifying components in an electrical schematic where AC is rectified to a DC voltage", "identifying tires", "identifying seats", "identifying lights only"]'::jsonb,0,'Rectifier schematic.','original'),
('127.888.d.23.I',4,'A diode in a rectifier circuit allows current to flow:','["both ways", "in one direction only", "in no direction", "only when cold"]'::jsonb,1,'Diode.','original'),
('127.888.d.23.J',3,'A mechanic uses a meter on a disconnected wire to see if it is complete from end to end. She is:','["measuring fuel", "cutting wire", "performing a continuity test to verify the condition of a conductor", "painting wire"]'::jsonb,2,'Continuity.','original'),
('127.888.d.23.J',4,'A continuity test on a good wire should show:','["a smell", "infinite ohms", "a spark", "near zero ohms or a beep"]'::jsonb,3,'Continuity reading.','original'),
('127.888.d.23.K',3,'A technician disconnects the load and measures resistance from the wire to airframe ground. She is:','["performing a test on a conductor for a short to ground", "ignoring the wire", "adding a load", "painting the wire"]'::jsonb,0,'Short to ground.','original'),
('127.888.d.23.K',4,'A low resistance between a wire and the airframe means:','["the wire is bonded safely", "the wire is shorted to ground", "the wire is good", "the wire is open"]'::jsonb,1,'Short found.','original'),
('127.888.d.24.A',3,'A student studies how supercooled water droplets freeze on wing leading edges and change lift. She is:','["describing seats", "describing tires", "explaining the causes and effects of aircraft icing", "avoiding icing"]'::jsonb,2,'Icing.','original'),
('127.888.d.24.A',4,'Ice on a wing is dangerous because it can:','["increase lift", "cool the engine", "improve control", "increase weight and reduce lift"]'::jsonb,3,'Ice effect.','original'),
('127.888.d.24.B',3,'A student labels an ice detector probe, a heated leading edge and a pneumatic boot on a diagram. She is:','["identifying the components of ice detection and anti-ice and deice systems", "labeling lights", "labeling seats", "labeling tires"]'::jsonb,0,'Anti-ice parts.','original'),
('127.888.d.24.B',4,'A pneumatic deice boot works by:','["spraying fuel", "inflating to break off ice", "heating the wing", "cooling the air"]'::jsonb,1,'Deice boot.','original'),
('127.888.d.24.C',3,'A mechanic explains how bleed air heats a wing leading edge to keep ice from forming. She is:','["describing seats", "avoiding ice", "explaining the basic operation of ice detection, anti-ice and deice systems", "describing tires"]'::jsonb,2,'Anti-ice operation.','original'),
('127.888.d.24.C',4,'Anti-ice systems are meant to:','["cool the wing", "remove ice after it forms", "add ice", "prevent ice from forming"]'::jsonb,3,'Anti-ice vs deice.','original'),
('127.888.d.24.D',3,'A student compares an electric wiper, a chemical rain repellent and a pneumatic jet of air for keeping a windshield clear. She is:','["explaining windshield rain control systems", "describing tires", "avoiding rain", "describing seats"]'::jsonb,0,'Rain control.','original'),
('127.888.d.24.D',4,'A pneumatic rain removal system clears water using:','["a sponge", "a stream of high-pressure air", "a heater", "a chemical"]'::jsonb,1,'Air rain removal.','original'),
('127.888.d.24.E',3,'A mechanic learns that running a wing anti-ice test on the ground for too long can overheat the leading edge. She is researching:','["paint choices", "no risks", "the risks of improper ice and rain control system testing", "tire brands"]'::jsonb,2,'Test risks.','original'),
('127.888.d.24.E',4,'Running a windshield wiper dry on a dry windshield can:','["cool it", "clean it", "protect it", "scratch the glass and damage the blades"]'::jsonb,3,'Dry wipers.','original'),
('127.888.d.24.F',3,'A student reads that deicing fluid left in open containers can contaminate surfaces and the environment. She is researching:','["the risks of improper storage and handling of deicing fluids", "no risks", "paint choices", "tire brands"]'::jsonb,0,'Deicing fluid.','original'),
('127.888.d.24.F',4,'People who handle deicing fluid should wear:','["sandals", "gloves and eye protection", "a necktie", "nothing"]'::jsonb,1,'Fluid PPE.','original'),
